use vstd::prelude::*;

verus! {
    fn two_sum(nums: &Vec<i32>, target: i32) -> (result: Vec<usize>)
        requires
            nums.len() >= 2,
        ensures
            result.len() == 2,
            result[0] < result[1],
            nums[result[0]] + nums[result[1]] == target,
    {
        let n = nums.len();
        let mut indices: Vec<usize> = Vec::new();

        // We will use a nested loop to find the two indices
        for i in 0..n
            invariant
                0 <= i <= n,
                indices.len() <= 2,
                forall(j: usize :: 0 <= j < indices.len() ==> indices[j] < n),
                forall(j: usize :: 0 <= j < indices.len() ==> nums[indices[j]] + target >= 0),
            {
                for j in (i + 1)..n
                    invariant
                        i < j <= n,
                        indices.len() <= 2,
                        forall(k: usize :: 0 <= k < indices.len() ==> indices[k] < n),
                {
                    if nums[i] + nums[j] == target {
                        indices.push(i);
                        indices.push(j);
                    }
                }
            }

        // We should have found exactly one pair of indices
        assert(indices.len() == 2);
        result = indices;
    }
}
